import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_src = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_fp16.h>
#include <cmath>

#define THREADS 256
#define MAX_S 256
#define DT 64

__global__ void sdpa_kernel(
    const __half* __restrict__ Q,
    const __half* __restrict__ K,
    const __half* __restrict__ V,
    __half* __restrict__ O,
    int B, int H, int S, int D,
    float scale
) {
    const int bh = blockIdx.x;
    const int i = threadIdx.x;

    const size_t qkv_base = (size_t)bh * (size_t)S * (size_t)D;
    const __half* q = Q + qkv_base;
    const __half* k = K + qkv_base;
    const __half* v = V + qkv_base;
    __half* o = O + qkv_base;

    float srow[MAX_S];
    __half prow[MAX_S];

    const int D2 = D >> 1;

    if (i < S) {
        const __half2* q2 = reinterpret_cast<const __half2*>(q + (size_t)i * (size_t)D);

        for (int j = 0; j < S; ++j) {
            const __half2* k2 = reinterpret_cast<const __half2*>(k + (size_t)j * (size_t)D);
            float dot = 0.0f;

            #pragma unroll 4
            for (int d2 = 0; d2 < D2; ++d2) {
                float2 qf = __half22float2(q2[d2]);
                float2 kf = __half22float2(k2[d2]);
                dot = fmaf(qf.x, kf.x, dot);
                dot = fmaf(qf.y, kf.y, dot);
            }

            srow[j] = dot * scale;
        }

        float mx = -INFINITY;
        for (int j = 0; j < S; ++j) {
            mx = fmaxf(mx, srow[j]);
        }

        float sum = 0.0f;
        for (int j = 0; j < S; ++j) {
            float e = expf(srow[j] - mx);
            sum += e;
            prow[j] = __float2half_rn(e);
        }

        float inv_sum = 1.0f / sum;
        for (int j = 0; j < S; ++j) {
            prow[j] = __float2half_rn(__half2float(prow[j]) * inv_sum);
        }
    }

    extern __shared__ __half shV[];

    for (int d0 = 0; d0 < D; d0 += DT) {
        const int total = S * DT;
        for (int idx = threadIdx.x; idx < total; idx += blockDim.x) {
            int r = idx / DT;
            int c = idx - r * DT;
            shV[idx] = v[(size_t)r * (size_t)D + (size_t)d0 + (size_t)c];
        }
        __syncthreads();

        if (i < S) {
            __half* orow = o + (size_t)i * (size_t)D + (size_t)d0;

            #pragma unroll 4
            for (int c = 0; c < DT; ++c) {
                float acc = 0.0f;
                for (int j = 0; j < S; ++j) {
                    float p = __half2float(prow[j]);
                    float vv = __half2float(shV[j * DT + c]);
                    acc = fmaf(p, vv, acc);
                }
                orow[c] = __float2half_rn(acc);
            }
        }
        __syncthreads();
    }
}

torch::Tensor sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "Q, K, V must be CUDA tensors");
    TORCH_CHECK(Q.scalar_type() == at::kHalf && K.scalar_type() == at::kHalf && V.scalar_type() == at::kHalf,
                "Q, K, V must be float16");
    TORCH_CHECK(Q.is_contiguous() && K.is_contiguous() && V.is_contiguous(),
                "Q, K, V must be contiguous");
    TORCH_CHECK(Q.dim() == 4 && K.dim() == 4 && V.dim() == 4, "Q, K, V must be 4D");
    TORCH_CHECK(Q.sizes() == K.sizes() && Q.sizes() == V.sizes(), "Q, K, V must have the same shape");

    const int B = (int)Q.size(0);
    const int H = (int)Q.size(1);
    const int S = (int)Q.size(2);
    const int D = (int)Q.size(3);

    TORCH_CHECK(S <= MAX_S, "sequence_length must be <= 256 for this kernel");
    TORCH_CHECK((D % DT) == 0, "embedding_dimension must be a multiple of 64");
    TORCH_CHECK((D % 2) == 0, "embedding_dimension must be even");

    auto O = torch::empty_like(Q);
    const float scale = 1.0f / std::sqrt((float)D);
    const size_t shmem_bytes = (size_t)S * (size_t)DT * sizeof(__half);

    auto stream = at::cuda::getCurrentCUDAStream();
    sdpa_kernel<<<B * H, THREADS, shmem_bytes, stream>>>(
        reinterpret_cast<const __half*>(Q.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(K.data_ptr<at::Half>()),
        reinterpret_cast<const __half*>(V.data_ptr<at::Half>()),
        reinterpret_cast<__half*>(O.data_ptr<at::Half>()),
        B, H, S, D, scale
    );

    return O;
}
'''

cpp_src = "torch::Tensor sdpa_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V);"

_mod = load_inline(
    name="custom_sdpa_single_kernel",
    cpp_sources=cpp_src,
    cuda_sources=cuda_src,
    functions=["sdpa_forward"],
    extra_cuda_cflags=["-O3", "--use_fast_math"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, Q: torch.Tensor, K: torch.Tensor, V: torch.Tensor) -> torch.Tensor:
        return _mod.sdpa_forward(Q, K, V)

